const fields = $input.item.json.body.data.fields;

// ── Step 1: Helper functions ──────────────────────────────────────

// Resolve dropdown option ID → label text
function getDropdownText(field) {
  if (!field || !field.value || !field.value[0]) return '';
  const selectedId = Array.isArray(field.value)
    ? field.value[0]
    : field.value;
  const match = field.options?.find(o => o.id === selectedId);
  return match ? match.text.trim() : '';
}

// Get plain text value safely
function getText(field) {
  if (!field) return '';
  if (Array.isArray(field.value)) return (field.value[0] ?? '').toString().trim();
  return (field.value ?? '').toString().trim();
}

// Parse budget label → numeric lower bound
// Handles: "1L above", "30k - 50k", "20k - 30k", "50K-1L"
function parseBudget(label) {
  if (!label) return 0;

  const s = label.toLowerCase()
    .replace(/[₹$,\s]/g, '')
    .replace(/above|plus|\+/g, '')
    .trim();

  function expand(str) {
    if (!str) return 0;
    str = str.trim();
    if (str.includes('l')) {
      return parseFloat(str.replace('l', '')) * 100000;
    }
    if (str.includes('k')) {
      return parseFloat(str.replace('k', '')) * 1000;
    }
    return parseFloat(str) || 0;
  }

  const parts = s.split('-');
  return expand(parts[0]);
}

// ── Step 2: Map fields by label ───────────────────────────────────

const fieldMap = {};
fields.forEach(f => {
  if (f.label) fieldMap[f.label] = f;  // skip null labels (checkbox)
});

// ── Step 3: Extract raw values ────────────────────────────────────

const raw = {
  source:       'tally',
  first_name:   getText(fieldMap['First name']),
  last_name:    getText(fieldMap['Last name']),
  email:        getText(fieldMap['Email']),
  job_title:    getText(fieldMap['Job title']),
  company:      getText(fieldMap['Company name']),
  company_size: getDropdownText(fieldMap['Company size']),
  budget_label: getDropdownText(fieldMap['Budget']),
  message:      getText(fieldMap['Message']),
  newsletter:   fieldMap['Checkbox'] ? true : false,
};

// ── Step 4: Clean and validate ────────────────────────────────────

const email     = (raw.email      || '').toLowerCase().trim();
const firstName = (raw.first_name || '').trim();
const lastName  = (raw.last_name  || '').trim();
const company   = (raw.company    || '').trim();
const jobTitle  = (raw.job_title  || '').trim();
const message   = (raw.message    || '').trim();
const budget    = parseBudget(raw.budget_label);

// Email validation — stops workflow if invalid
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
if (!emailValid) {
  throw new Error(`Invalid or missing email: "${email}"`);
}

// ── Step 5: Return clean output ───────────────────────────────────

return [{
  json: {
    // Identity
    source:        raw.source,
    first_name:    firstName,
    last_name:     lastName,
    full_name:     `${firstName} ${lastName}`.trim(),
    email:         email,
    phone:         '',              // not collected in your form

    // Professional
    job_title:     jobTitle,
    company:       company,
    company_size:  raw.company_size,  // "1-10", "100-1000" etc

    // Budget
    budget_label:  raw.budget_label,  // "1L above", "30k - 50k" etc
    budget:        budget,            // 100000, 30000 etc

    // Message
    message:       message,

    // Meta
    // Replace this:
normalised_at: new Date().toISOString(),

// With this:
normalised_at: new Date().toLocaleString('en-IN', { 
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
}),

    // Flags
    has_company:   company.length > 0,
    has_budget:    budget > 0,
  }
}];

// Get normalised lead data from Normalise Payload node
const lead = $('Normalise Payload').item.json;

let score = 0;
const reasons = [];

// ── 1. Budget Score (0–40 pts) ────────────────────────
// Using your actual Tally budget options
const budget = lead.budget || 0;

if      (budget >= 100000) { score += 40; reasons.push('budget:high');    }
else if (budget >= 50000)  { score += 25; reasons.push('budget:mid');     }
else if (budget >= 30000)  { score += 15; reasons.push('budget:low');     }
else if (budget >= 20000)  { score += 5;  reasons.push('budget:minimal'); }
else                       { score += 0;  reasons.push('budget:none');    }

// ── 2. Company Size Score (0–35 pts) ──────────────────
// Using your actual Tally dropdown options:
// "1-10", "10-100", "100-1000", "1000+"
const companySize = (lead.company_size || '').toLowerCase();

    // Replace the company size section with this:
if      (companySize === '1000 +')   { score += 35; reasons.push('size:enterprise');  }
else if (companySize === '100-1000') { score += 20; reasons.push('size:mid-market'); }
else if (companySize === '10-100')   { score += 10; reasons.push('size:smb');        }
else if (companySize === '1-10')     { score += 3;  reasons.push('size:micro');      }
else                                 { score += 0;  reasons.push('size:unknown');    }                          

// ── 3. Job Title Seniority Score (0–25 pts) ───────────
const title = (lead.job_title || '').toLowerCase();

if      (/ceo|cto|coo|founder|owner|president/.test(title)) { score += 25; reasons.push('seniority:c-suite');    }
else if (/vp|vice president|director/.test(title))          { score += 20; reasons.push('seniority:vp');         }
else if (/manager|lead|head/.test(title))                   { score += 15; reasons.push('seniority:manager');    }
else if (/engineer|developer|analyst|designer/.test(title)) { score += 8;  reasons.push('seniority:ic');         }
else if (/intern|trainee|junior/.test(title))               { score += 2;  reasons.push('seniority:junior');     }
else                                                         { score += 5;  reasons.push('seniority:other');      }

// ── 4. Determine Tier ─────────────────────────────────
let tier;
if      (score >= 70) tier = 'high';
else if (score >= 40) tier = 'mid';
else                  tier = 'low';

// ── 5. Return scored lead ─────────────────────────────
return [{
  json: {
    // All original lead fields
    source:        lead.source,
    first_name:    lead.first_name,
    last_name:     lead.last_name,
    full_name:     lead.full_name,
    email:         lead.email,
    phone:         lead.phone,
    job_title:     lead.job_title,
    company:       lead.company,
    company_size:  lead.company_size,
    budget_label:  lead.budget_label,
    budget:        lead.budget,
    message:       lead.message,
    normalised_at: lead.normalised_at,

    // Enrichment placeholders (empty for now — Apollo skipped)
    enriched_industry:   '',
    enriched_employees:  '',
    enriched_linkedin:   '',

    // Scoring results
    lead_score:    score,
    lead_tier:     tier,
    score_reasons: reasons.join(', '),
    scored_at:     new Date().toISOString(),
  }
}];

